package com.fakelegacy.order.pricing;

import java.math.BigDecimal;

public class TierDiscountStep extends AbstractDiscountStep {

    @Override
    protected BigDecimal compute(LineDraft line, String tier) {
        return line.gross().multiply(PricingConstants.tierRate(tier));
    }

    @Override
    protected void store(LineDraft line, BigDecimal amount) {
        line.setDiscountTier(amount);
    }
}
